void ZoneBlock::setPortal(Bool add, Int portalID)
{
	if (!portalID)
		return;
	Int i;
	for (i = 0; i < m_numPortals; ++i)
	{
		if (m_portals[i] == portalID)
			break;
	}
	if (add)
	{
		if (i >= m_numPortals && m_numPortals < MAX_PORTALS)
			m_portals[m_numPortals++] = portalID;
	}
	else if (i < m_numPortals)
	{
		--m_numPortals;
		m_portals[i] = m_portals[m_numPortals];
	}
}

